"""Protocol 7 against vectors generated by ldnrs 0.0.3's own client, plus an Ethernet daemon peer."""
import json
import socket
import struct
from pathlib import Path
from types import SimpleNamespace

import ldn
import pytest
import trio
from trio.testing import memory_stream_pair

from pokeldn.ldn import api, ldnrs, radios, userspace_ip

VECTORS = json.loads((Path(__file__).parent / "data" / "ldnrs_protocol7.json").read_text())
RAW = bytes.fromhex(VECTORS["network"])
REPLY = bytes.fromhex(VECTORS["network_reply"])


async def exact(stream, size):
    data = bytearray()
    while len(data) < size:
        chunk = await stream.receive_some(size - len(data))
        if not chunk:
            raise EOFError("peer closed")
        data.extend(chunk)
    return bytes(data)


async def frame(stream):
    op, sub, seq, size = struct.unpack("<BBII", await exact(stream, 10))
    return op, sub, seq, await exact(stream, size)


async def send(stream, seq, body, op=0x80):
    # Split headers and bodies so reads must cope with stream fragmentation.
    wire = struct.pack("<BBII", op, 0, seq, len(body)) + body
    for start in range(0, len(wire), 7):
        await stream.send_all(wire[start:start + 7])


async def handshake(stream):
    op, sub, seq, body = await frame(stream)
    assert (op, sub) == (1, 0)
    assert body == bytes.fromhex("070000000007000000706f6b656c646e0100000031")
    await send(stream, seq, b"\0\0" + struct.pack("<I", 7) + b"\5\0\0\0" + b"0.0.3" + b"\7\0\1")
    op, sub, seq, body = await frame(stream)
    assert (op, sub) == (0x10, 0x60)
    assert body == b"\x0f\0\0\0test_key = 0102"
    await send(stream, seq, b"\0\0")


def params(host):
    param = ldn.CreateNetworkParam() if host else ldn.ConnectNetworkParam()
    param.keys = {"test_key": b"\1\2"}
    param.password, param.name, param.app_version, param.device_id = b"password", b"POKELDN", 88, 1234
    if host:
        param.local_communication_id = 0x0100610011000000
        param.application_data = b"beacon"
        param.ssid, param.server_random = bytes(range(16)), bytes(range(16, 32))
        param.channel, param.protocol = 6, 3
    else:
        param.network = ldnrs.network_info(ldnrs.Reader(RAW))
    return param


def test_scan_matches_upstream_and_passes_keys_to_the_daemon(monkeypatch):
    monkeypatch.setenv("POKELDN_RADIO", "ldnrs:")

    async def run():
        client, server = memory_stream_pair()
        async def open_pipe(path):
            assert path == r"\\.\pipe\ldnd"
            return client
        monkeypatch.setattr(ldnrs.Pipe, "open", open_pipe)
        async def peer():
            async with server:
                await handshake(server)
                op, sub, seq, body = await frame(server)
                assert (op, sub, body.hex()) == (0x10, 0x20, VECTORS["scan"])
                await send(server, seq, b"\0\0\1\0\0\0" + RAW)
                await server.receive_some(1)
        async with trio.open_nursery() as nursery:
            nursery.start_soon(peer)
            result = await api.scan({"test_key": b"\1\2"}, channels=[1, 6, 11],
                                    dwell_time=0.6, protocols=[1, 3])
            assert result[0].participants[1].ip_address == "169.254.21.2"
            assert result[0].application_data == b"beacon"
    trio.run(run)


@pytest.mark.parametrize("host", [False, True], ids=["join", "host"])
def test_network_bridges_real_udp_frames_and_closes_channels(monkeypatch, host):
    monkeypatch.setenv("POKELDN_RADIO", "ldnrs:")
    async def run():
        client, server = memory_stream_pair()
        async def open_pipe(path):
            return client
        monkeypatch.setattr(ldnrs.Pipe, "open", open_pipe)
        received, sent = trio.Event(), trio.Event()
        async def peer():
            async with server:
                await handshake(server)
                op, sub, seq, body = await frame(server)
                assert (op, sub, body.hex()) == (0x10, 0x31 if host else 0x30,
                                               VECTORS["host" if host else "join"])
                await send(server, seq, b"\0\0" + (REPLY[:-1] + b"\0" if host else REPLY))
                op, sub, seq, body = await frame(server)
                assert (op, sub, body) == (0x10, 0x51, b"\7\0\0\0")
                await send(server, seq, b"\0\0\11\0\0\0")
                op, sub, seq, body = await frame(server)
                assert (op, sub, seq) == (0x82, 0, 0)
                assert body[:4] == b"\11\0\0\0"
                ethernet = body[4:]
                assert ethernet[:14] == bytes.fromhex(
                    "0200000000020200000000010800" if host else "0200000000010200000000020800")
                assert ethernet[-4:] == b"ping"
                received.set()
                # An independently assembled IPv4/UDP Ethernet reply, checksum 0 valid for UDP/IPv4.
                packet = bytes.fromhex(
                    "0200000000010200000000020800 45000020000000004011cd9a a9fe1502 a9fe1501"
                    "30393039000c0000" if host else
                    "0200000000020200000000010800 45000020000000004011cd9a a9fe1501 a9fe1502"
                    "30393039000c0000") + b"pong"
                await send(server, 0, b"\11\0\0\0" + packet, op=0x82)
                sent.set()
                if host:
                    op, sub, seq, body = await frame(server)
                    assert (op, sub, body) == (0x10, 0x40, b"\7\0\0\0\3\0\0\0new")
                    await send(server, seq, b"\0\0")
                    # The participant entry uses the upstream vector's second synthetic slot.
                    p = bytes.fromhex("a9fe15020200000000020107000000504f4b454c444e580000")
                    await send(server, 0, b"\3\7\0\0\0\1" + p, op=0x81)
                    await send(server, 0, b"\4\7\0\0\0\1" + p, op=0x81)
                    await send(server, 0, b"\5\7\0\0\0\3", op=0x81)
                for expected, handle in [(0x52, 9), (0x32, 7)]:
                    op, sub, seq, body = await frame(server)
                    assert (op, sub, body) == (0x10, expected, struct.pack("<I", handle))
                    await send(server, seq, b"\3\0" if host else b"\0\0")
                await server.receive_some(1)
        async with trio.open_nursery() as nursery:
            nursery.start_soon(peer)
            param = params(host)
            name = param.ifname_tap if host else param.ifname
            with trio.fail_after(5):
                async with (api.create_network(param) if host else api.connect(param)) as net:
                    sock = userspace_ip.udp_socket(name, 12345)
                    sock.setblocking(False)
                    try:
                        peer_ip = "169.254.21.2" if host else "169.254.21.1"
                        sock.sendto(b"ping", (peer_ip, 12345))
                        await received.wait()
                        await sent.wait()
                        while True:
                            try:
                                answer = sock.recvfrom()
                                break
                            except BlockingIOError:
                                await trio.sleep(0)
                        assert answer == (b"pong", (peer_ip, 12345))
                        if host:
                            net.set_application_data(b"new")
                            assert type(await net.next_event()).__name__ == "JoinEvent"
                            assert type(await net.next_event()).__name__ == "LeaveEvent"
                            assert not net.info().participants[1].connected
                            assert (await net.next_event()).reason == 3
                    finally:
                        sock.close()
            assert userspace_ip.lookup(name) is None
    trio.run(run)


@pytest.mark.parametrize("failure", ["version", "not-ready", "error", "oversize", "eof"])
def test_bad_daemon_fails_promptly_and_releases_stream(monkeypatch, failure):
    monkeypatch.setenv("POKELDN_RADIO", "ldnrs:")
    async def run():
        client, server = memory_stream_pair()
        async def open_pipe(path):
            return client
        monkeypatch.setattr(ldnrs.Pipe, "open", open_pipe)
        async def peer():
            async with server:
                _, _, seq, _ = await frame(server)
                if failure == "eof":
                    return
                if failure == "oversize":
                    await server.send_all(struct.pack("<BBII", 0x80, 0, seq, 262145))
                elif failure == "error":
                    await send(server, seq, b"\5\1\4\0\0\0busy")
                else:
                    await send(server, seq, b"\0\0" + struct.pack("<I", 8 if failure == "version" else 7)
                               + b"\5\0\0\0" + b"0.0.3\7\0" + bytes([failure != "not-ready"]))
                await server.receive_some(1)
        async with trio.open_nursery() as nursery:
            nursery.start_soon(peer)
            with trio.fail_after(2), pytest.raises(ExceptionGroup) as caught:
                await api.scan()
            error = caught.value
            while isinstance(error, BaseExceptionGroup):
                assert len(error.exceptions) == 1
                error = error.exceptions[0]
            expected = {"version": "protocol 8", "not-ready": "not ready", "error": "busy",
                        "oversize": "256 KiB", "eof": "disconnected"}
            assert expected[failure] in str(error)
    trio.run(run)


def test_existing_radios_keep_the_bundled_library(monkeypatch):
    monkeypatch.delenv("POKELDN_RADIO", raising=False)
    assert api.scan is ldn.scan
    assert radios.join_timeout(8) == 8
    monkeypatch.setenv("POKELDN_RADIO", "ldnrs:")
    assert radios.join_timeout(8) == 90
    monkeypatch.setattr(radios, "sys", SimpleNamespace(platform="win32"))
    assert radios.radio("ldnrs").label == "USB Wi-Fi (Windows, ldnrs)"


@pytest.mark.skipif(__import__("sys").platform != "win32", reason="Windows named-pipe transport")
def test_windows_named_pipe_scan_without_an_adapter(monkeypatch):
    import ctypes
    from ctypes import wintypes
    import os

    path = rf"\\.\pipe\pokeldn-test-{os.getpid()}"
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    handle_type = wintypes.HANDLE
    kernel.CreateNamedPipeW.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD,
                                       wintypes.DWORD, wintypes.DWORD, wintypes.DWORD,
                                       wintypes.DWORD, ctypes.c_void_p]
    kernel.CreateNamedPipeW.restype = handle_type
    kernel.ConnectNamedPipe.argtypes = [handle_type, ctypes.c_void_p]
    kernel.ConnectNamedPipe.restype = wintypes.BOOL
    kernel.ReadFile.argtypes = [handle_type, ctypes.c_void_p, wintypes.DWORD,
                               ctypes.POINTER(wintypes.DWORD), ctypes.c_void_p]
    kernel.ReadFile.restype = wintypes.BOOL
    kernel.WriteFile.argtypes = kernel.ReadFile.argtypes
    kernel.WriteFile.restype = wintypes.BOOL
    kernel.CloseHandle.argtypes = [handle_type]
    kernel.CloseHandle.restype = wintypes.BOOL
    handle = kernel.CreateNamedPipeW(path, 3, 0, 1, 65536, 65536, 0, None)
    assert handle not in (None, ctypes.c_void_p(-1).value)
    monkeypatch.setenv("POKELDN_RADIO", "ldnrs:" + path)

    def read(size):
        data = bytearray()
        while len(data) < size:
            buf, count = ctypes.create_string_buffer(size - len(data)), wintypes.DWORD()
            assert kernel.ReadFile(handle, buf, len(buf), ctypes.byref(count), None)
            assert count.value
            data.extend(buf.raw[:count.value])
        return bytes(data)

    def reply(sequence, body):
        data = struct.pack("<BBII", 0x80, 0, sequence, len(body)) + body
        count = wintypes.DWORD()
        assert kernel.WriteFile(handle, data, len(data), ctypes.byref(count), None)
        assert count.value == len(data)

    def peer():
        try:
            assert kernel.ConnectNamedPipe(handle, None) or ctypes.get_last_error() == 535
            op, sub, seq, size = struct.unpack("<BBII", read(10))
            assert (op, sub) == (1, 0)
            read(size)
            reply(seq, b"\0\0\7\0\0\0\5\0\0\0" + b"0.0.3\7\0\1")
            op, sub, seq, size = struct.unpack("<BBII", read(10))
            assert (op, sub) == (0x10, 0x20)
            read(size)
            reply(seq, b"\0\0\0\0\0\0")
            # Keep the server alive until the client has closed its side.
            buf, count = ctypes.create_string_buffer(1), wintypes.DWORD()
            kernel.ReadFile(handle, buf, 1, ctypes.byref(count), None)
        finally:
            kernel.CloseHandle(handle)

    async def run():
        async with trio.open_nursery() as nursery:
            nursery.start_soon(trio.to_thread.run_sync, peer)
            with trio.fail_after(5):
                assert await api.scan() == []
    trio.run(run)
